for i in items:
  rs = [('', r) for r in i.get('rules', [])] + [('тень', r) for r in i.get('shadow', {}).get('rules', [])] + [('розыгрыш', p['rule']) for p in i.get('play', []) if 'rule' in p]
  if i.get('riskRule'): rs.append(('риск', i['riskRule']))
  if i.get('sellRule'): rs.append(('скупка', i['sellRule']))
  for kind, r in rs:
    hit = next((x for x in S if x[0] in r), None)
    rows.append((i['kind'], i['name'], kind, r, hit[1] if hit else '❓', hit[2] if hit else ''))
done = sum(1 for r in rows if r[4] == '✅')
