print(f'Всего {len(rows)}: ✅ работает — {done}; ⏳ «Род» (этап 5) — {sum(1 for r in rows if r[4].startswith("⏳"))}; 🟡 частично — {sum(1 for r in rows if r[4]=="🟡")}; ➖ нет карт, которые это вызывают — {sum(1 for r in rows if r[4]=="➖")}; ❓ не разобрано — {sum(1 for r in rows if r[4]=="❓")}.\n')
